```ts
declare const tools: { mcp__kmp__kmp_forward(args: { [key: string]: unknown; } | { [key: string]: unknown; } | { [key: string]: unknown; }): Promise<CallToolResult<{
  coverage?: {
  // Per-dimension returned counts and presence flags.
  dimensions?: unknown[];
  // Dimension scope ids included in the result.
  included?: Array<string>;
  // Requested dimension scope ids not present in the result.
  missing?: Array<string>;
  // Dimension selection requested by the caller.
  requested?: { [key: string]: unknown; } | null;
};
  // Temporal entries in traversal order. ref/kind always remain; fields selects text, coordinates and metadata. Each reduced entry has an executable detail_action for a fresh full selected-packet read with the original verb, cutoff, interval, scope, window and limits. Replay a shared action once, not once per entry.
  entries?: unknown[];
  // Execute these calls unchanged. While page.has_more, reconstruct this packet first; once complete, these calls navigate remaining history (Near can offer both directions).
  next_actions?: Array<{
  // Complete bound arguments, including the continuation cursor or a required budget adjustment.
  arguments?: { [key: string]: unknown; };
  // Native temporal tool to execute.
  tool?: string;
}>;
  page?: {
  // More items remain; this page is incomplete.
  has_more?: boolean;
  // Present when the next complete item cannot fit. next_actions supplies a retry with this budget that admits at least one item.
  minimum_progress_bytes?: number;
  // Opaque cursor for page.cursor; execute the complete next_actions call.
  next_cursor?: string | null;
  // Expansion items reconstructed before this page.
  offset?: number;
  // Items returned on this page.
  returned?: number;
  // Per-section returned_on_page, remaining and total counts. Append each section across pages before concluding from proof.
  sections?: { [key: string]: unknown; };
  // Total entry and proof expansion items in the selection.
  total?: number;
};
  proof?: {
  // Searched abouts with no entry in the selected interval or effective at the selected instant; empty for an unbounded read.
  abouts_empty_in_selection?: unknown[];
  // Abouts read under dimensions.scope, current one first. Refs retain ownership; this list distinguishes searched from unsearched abouts.
  abouts_selected?: unknown[];
  // Selected instant, including the time resolved from a ref cursor; null if unrequested.
  as_of?: string | null;
  // Selected occurred/observed/ingested/validity clock, or default precedence; null at the memory's own frontier.
  axis?: string | null;
  // Temporal reads use medium when entries were returned and unknown when none were returned; this is not relation-writer certainty.
  confidence?: string;
  // Explicit contradictions whose entries are both still live; distinct from supersession.
  conflicts?: unknown[];
  // With include.dependencies, full stored dependency records with coordinates admitted by the proof boundary. These support the selected entries; they are not additional matches in the history window. fields does not shorten proof entries.
  entries?: unknown[];
  // Verbatim stored text; metadata.proof_role distinguishes claim from evidence. Retrieval metadata never changes that text. reached_by items are indirect proof, never answers or citations in because; reached_from, reached_via and reached_hops identify their route. On citations, bridged_terms names cross-language word pairs; restated_from and restated_via identify a writer-declared restatement; matched_via: summary and summary_terms identify words matched through the writer's English summary_en, not the canonical text.
  evidence?: unknown[];
  // Entries past exclusive valid_until at the temporal cursor, recall as_of/interval end, or otherwise the memory's latest instant. Expiry needs no replacement.
  expired?: unknown[];
  // Reachable items not returned; a signal to expand.
  frontier_size?: number;
  // With include.dependencies, bounded writer-declared neighborhoods. Members resolve in entries or proof.entries after all pages. Source passages and typed links remain in proof.evidence/path. Anonymous counts describe only the selected scoped graph, never semantic sufficiency.
  groups?: Array<{
  // Maximum expansion hops from this seed.
  max_hops?: number;
  // Maximum members, including the seed.
  max_members?: number;
  // Seed and available dependency entries in deterministic discovery order.
  member_refs?: Array<string>;
  // Distinct eligible frontier members not expanded because of hop or member limits.
  omitted_by_limit?: number;
  // The selected temporal entry.
  seed_ref?: string;
  // Distinct endpoints without an eligible body under this read; identities are not disclosed.
  unavailable_in_selection?: number;
}>;
  // Selected half-open [start,end) span, or null.
  interval?: { [key: string]: unknown; } | null;
  // Typed relations contributing to ordering. Their prose may improve a match, never promote unrelated evidence into an answer.
  matched_relations?: unknown[];
  // Question terms matching retrieved evidence.
  matched_terms?: unknown[];
  // What was sought but not found: no retrieval or no evidence bearing on the question. Non-empty with UNKNOWN.
  missing?: unknown[];
  // On interval UNKNOWN, nearest match outside it: ref, time and axis. Distinguishes not then from not known; otherwise null.
  nearest_outside?: { [key: string]: unknown; } | null;
  // Traversal connecting cited evidence.
  path?: unknown[];
  // Replaced entries with superseded_by and why. Historical state, distinct from contradiction; not current advice.
  superseded?: unknown[];
};
  // Response-shape metrics; null when the backend supplied none.
  quality?: {
  // Share of returned relations that explain rather than merely connect; reflects the stored writing.
  causal_density?: number;
  // Share of returned nodes that carry stored detail.
  detail_coverage?: number;
  // Returned node-detail count.
  details?: number;
  // Returned node count.
  nodes?: number;
  // Returned relation count.
  relationships?: number;
  // Whether the rendering dropped anything.
  truncated?: boolean;
} | null;
  // Typed raw audit refs for selected entries when include.raw_refs=true.
  raw_refs?: unknown[];
  selection?: {
  // Entries selected for this packet before response pagination.
  entries?: number;
  fields?: {
  // Fields returned on each entry; ref and kind always remain.
  included?: Array<string>;
  // Entry fields available through each returned detail_action; omitted fields are not empty values.
  omitted?: Array<string>;
};
  // More matching history remains outside this packet. Complete its response pages before following the returned navigation actions.
  has_more?: boolean;
  // Matching temporal entries reported by the kernel before its entry/window limit.
  matching_entries?: number;
  // Present with refs: the explicit entry focus. Dependency records may have other refs within the same scope and time.
  requested_refs?: Array<string>;
  // selected_packet: top-level summary, coverage and quality refer to this bounded selection, not the current response page or all memory.
  scope?: string;
  // Requested refs not matching this history selection; may be absent, out of scope/filter/clock/direction. Does not prove nonexistence. Independent of response-page completion.
  unmatched_ref_count?: number;
};
  // Concise description of the temporal selection.
  summary?: string;
  // Direction, clock axis and entry interval. requested/resolved are null for a direct interval without an initial cursor.
  temporal?: { [key: string]: unknown; } | null;
  // Non-empty warnings qualify success; retain them.
  warnings?: Array<string>;
}>>; };
```

